#include "movedetail_schema.h"

Z6DetailJson& Z6DetailJson::operator=(const Z6DetailJson& other) {
    if (this != &other) {
        pit_ = other.pit_;
        pit_valid_ = other.pit_valid_;
    }
    return *this;
}

bool Z6DetailJson::validate(const std::string& json_str) {
    try {
        auto j = json::parse(json_str);
        if (!j.is_object()) return false;
        if (!j.contains("Pit")) return false;
        if (j.contains("Pit")) {
            if (!j["Pit"].is_object()) return false;
        }
        return true;
    } catch (...) {
        return false;
    }
}

bool Z6DetailJson::getPit(Z6PitJson& val) const {
    if (!pit_valid_) return false;
    val = pit_;
    return true;
}

void Z6DetailJson::setPit(const Z6PitJson& val) {
    pit_ = val;
    pit_valid_ = true;
}

void Z6DetailJson::from_json(const std::string& json_str) {
    json j = json::parse(json_str);
        if (j.contains("Pit")) {
            pit_.from_json(j["Pit"].dump());
            pit_valid_ = true;
        }
}

std::string Z6DetailJson::to_json() const {
    json j;
        if (pit_valid_) {
            j["Pit"] = json::parse(pit_.to_json());
        }
    return j.dump();
}

